//! Protobuf types generated by `build.rs`.
//!
//! Each module contains the prost message types and the proto3-JSON serde impls from pbjson.
//! Well-known types (`google.protobuf.*`) resolve to `pbjson_types`.
//!
//! Timestamps serialize through chrono's RFC 3339 output (`pbjson-types` default), not the
//! canonical proto3-JSON `Z` form. Nothing may sign or hash the JSON serialization of
//! timestamps. Signatures cover protobuf bytes or headers, never JSON text.

/// The A2A protocol package `lf.a2a.v1`.
pub mod a2a {
    #![allow(clippy::all, missing_docs)]
    include!(concat!(env!("OUT_DIR"), "/lf.a2a.v1.rs"));
    include!(concat!(env!("OUT_DIR"), "/lf.a2a.v1.serde.rs"));
}

/// The A2A-Bus extension package `a2abus.v1`.
pub mod a2abus {
    #![allow(clippy::all, missing_docs)]
    include!(concat!(env!("OUT_DIR"), "/a2abus.v1.rs"));
    include!(concat!(env!("OUT_DIR"), "/a2abus.v1.serde.rs"));
}

/// The `google.rpc` package (`Status`, error details).
pub mod rpc {
    #![allow(clippy::all, missing_docs)]
    include!(concat!(env!("OUT_DIR"), "/google.rpc.rs"));
    include!(concat!(env!("OUT_DIR"), "/google.rpc.serde.rs"));
}
